package com.healthcare.portal.dto; import com.healthcare.portal.entity.MedicalRecord; import java.time.LocalDateTime; public record MedicalRecordResponse(Long id,Long patientId,Long doctorId,Long appointmentId,String diagnosis,String notes,String documentUrl,LocalDateTime createdAt){public static MedicalRecordResponse from(MedicalRecord r){return new MedicalRecordResponse(r.getId(),r.getPatient().getId(),r.getDoctor().getId(),r.getAppointment()==null?null:r.getAppointment().getId(),r.getDiagnosis(),r.getNotes(),r.getDocumentUrl(),r.getCreatedAt());}}
